      <mesh ref={ringRef} rotation={[Math.PI / 2, 0, 0]}>
        <torusGeometry args={[0.8, 0.008, 16, 64]} />
        <meshBasicMaterial
          color="#ffffff"
          transparent
          opacity={0.04}
          toneMapped={false}
        />
      </mesh>

      {/* "click to begin" text below the void */}
      <Html position={[0, -1.2, 0]} center>
